function taxonomyChain(taxonomy,node){const result=[];let current=node;while(current){result.unshift(current);current=current.parent?taxonomy.find(item=>item.id===current.parent):null;}return result;}
function nextRecallState(fm,rating,now=Date.now()){
  const reps=Math.max(0,Number(fm.recall_reps)||0),interval=Math.max(0,Number(fm.recall_interval_days)||0),next={recall_reviewed_at:new Date(now).toISOString(),recall_last_rating:rating};
  if(rating==='forgot'){next.recall_reps=0;next.recall_interval_days=1;next.recall_lapses=(Number(fm.recall_lapses)||0)+1;}
  else if(rating==='fuzzy'){next.recall_reps=Math.max(1,reps);next.recall_interval_days=Math.max(1,Math.ceil((interval||1)*1.4));}
  else{next.recall_reps=reps+1;next.recall_interval_days=reps===0?1:reps===1?3:Math.min(90,Math.ceil((interval||3)*2));}
  next.recall_due_at=new Date(now+next.recall_interval_days*86400000).toISOString();return next;
}
module.exports.__test.nextRecallState=nextRecallState;
module.exports.__test.taxonomyChain=taxonomyChain;

