  const moduleList=this.leftPane.createDiv({cls:'th-module-list'});for(const module of modules){const row=moduleList.createDiv({cls:'th-module-item'});const pick=row.createEl('button',{text:module.name,cls:'th-module-pick'});pick.toggleClass('is-active',this.module===module.name);pick.onclick=()=>{this.module=module.name;this.typePath='';this.teacher='';this.render();};const actions=row.createDiv({cls:'th-row-actions'});const rename=actions.createEl('button',{text:'改名',attr:{'aria-label':'重命名模块'}});rename.onclick=()=>new TextEntryModal(this.app,{title:'重命名模块',value:module.name,onSave:async name=>{const oldName=module.name;await plugin.renameTaxonomy(module,name);if(this.module===oldName)this.module=name;this.render();}}).open();const remove=actions.createEl('button',{text:'删除',attr:{'aria-label':'删除模块'}});remove.onclick=()=>new ConfirmEntryModal(this.app,'移除此模块分类及下级题型？对应笔记会保留，分类字段会被清除。',async()=>{const oldName=module.name;await plugin.removeTaxonomy(module);if(this.module===oldName){this.module=modules.find(x=>x!==module)?.name||'';this.typePath='';this.teacher='';}this.render();}).open();}
